use openwurli_dsp::{WurliEngine,CircuitMode};
fn main(){println!("voices,depth,samples,final_iter_sum,fallbacks,substeps,refactors,max_final_iter,adapter_resets,nr_failed_resets,seven_repeats_audio_hash,recovery_ms,render_ms");for n in [0,1,6,32,64]{for depth in [0.0,0.5]{let mut e=WurliEngine::new_with_circuit_mode(48000.0,CircuitMode::Heavy);e.set_tremolo_depth(depth);e.set_noise_enabled(false);e.warm_up();let before=e.review_stats();let before_ns=openwurli_dsp::gen_power_amp::REVIEW_FALLBACK_NS.load(std::sync::atomic::Ordering::Relaxed);let notes:Vec<_>=if n<=6{[48,55,60,63,67,70][..n].to_vec()}else{(0..n).map(|i|33+i as u8).collect()};for note in notes{e.note_on(note,0.95);}let mut b=[0.0f32;256];let mut audio=Vec::new();let clock=std::time::Instant::now();for _ in 0..94{e.render(&mut b);audio.extend_from_slice(&b);}let mut hash=0u64;for _ in 0..7{for s in &audio{hash=hash.wrapping_mul(16777619)^s.to_bits() as u64;}}let elapsed=clock.elapsed().as_secs_f64()*1000.0;let after=e.review_stats();let ns=openwurli_dsp::gen_power_amp::REVIEW_FALLBACK_NS.load(std::sync::atomic::Ordering::Relaxed)-before_ns;print!("{n},{depth}");for i in 0..8 {print!(",{}",if i==5{after[i]}else{after[i]-before[i]});}println!(",{hash},{},{}",ns as f64/1e6,elapsed);}}}
